  Lemma shad_aregion : forall c, shad (aregion L c) = shad (al_space_beg L) + 536870912 * c
    /\ shad (al_space_beg L) mod 4096 = 0 /\ 4096 <= shad (al_space_beg L) /\ shad (al_space_beg L) + 17179869184 <= 2^64.
Proof.
