  Lemma lattice_rng : forall c, 1 <= c < K_NUM_CLASSES ->
       rng RNG (shad (aregion L c) - 4096) 8192
    /\ rng RNG (shad (aregion L c) - 4096) 4096
    /\ (forall k, 0 <= k <= 14336 -> rng RNG (shad (aregion L c) + 32768 * k) 4096).
Proof.
